36	export const loader = async ({ request }: LoaderFunctionArgs) => {
37	  const { session } = await authenticate.admin(request);
38	  const shop = session.shop;
39	
40	  let config = await db.widgetConfig.findUnique({ where: { shop } });
41	
42	  if (!config) {
43	    config = await db.widgetConfig.create({ data: { shop } });
44	  }
45	
46	  const subscription = await getShopSubscription(shop);
47	
48	  return { config, subscription };
49	};
