51	// Helper: sync widget config to an App Installation metafield so the
52	// storefront Liquid block can read it via app.metafields.zip_checker.widget_config.value
53	//
54	// IMPORTANT: ownerId MUST be the App Installation GID (not the Shop GID).
55	// app.metafields in Liquid only surfaces metafields owned by the App Installation.
56	// Using the Shop GID writes to shop metafields which are invisible to app.metafields.
57	async function syncConfigMetafield(
58	  admin: Awaited<ReturnType<typeof authenticate.admin>>["admin"],
59	  configData: Record<string, unknown>,
60	) {
61	  try {
62	    // Step 1: get the App Installation GID
63	    const installResponse = await admin.graphql(
64	      `query { currentAppInstallation { id } }`,
65	    );
66	    const installJson = (await installResponse.json()) as {
67	      data: { currentAppInstallation: { id: string } };
68	    };
69	    const appInstallationGid = installJson.data.currentAppInstallation.id;
70	
71	    // Step 2: write the metafield to the App Installation
72	    // Namespace must be plain "zip_checker" (no "$app:" prefix) for App Installation metafields.
73	    // The Liquid block reads: app.metafields.zip_checker.widget_config.value
74	    const metaResponse = await admin.graphql(
75	      `mutation MetafieldsSet($metafields: [MetafieldsSetInput!]!) {
76	        metafieldsSet(metafields: $metafields) {
77	          metafields { id namespace key }
78	          userErrors { field message }
79	        }
80	      }`,
81	      {
82	        variables: {
83	          metafields: [
84	            {
85	              ownerId: appInstallationGid,
86	              namespace: "zip_checker",
87	              key: "widget_config",
88	              type: "json",
89	              value: JSON.stringify(configData),
90	            },
91	          ],
92	        },
93	      },
94	    );
95	    await metaResponse.json();
96	
97	    // userErrors are non-fatal — the API fallback still works
98	  } catch {
99	    // Non-fatal — the API fallback still works
100	  }

100	  }
101	}
