316	// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
317	// Handles @keyframes/@font-face (pass-through), @media (recursive scoping),
318	// and regular selectors (prefixed with container ID).
319	function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
320	  if (!rawCss) return "";
321	  // Sanitize the same way the public API does (mirrors api.widget-config.tsx)
322	  const css = rawCss
323	    .replace(/<style\b[^>]*>/gi, "")
324	    .replace(/<\/style>/gi, "")
325	    .replace(/@import\b[^;]*(;|$)/gi, "")
326	    .replace(/\bexpression\s*\(/gi, "")
327	    .replace(/url\s*\(\s*['"]?\s*javascript\s*:/gi, "url(")
328	    .replace(/url\s*\(\s*['"]?\s*data\s*:/gi, "url(");
329	  let result = "";
330	  let i = 0;
331	  while (i < css.length) {
332	    // Skip whitespace
333	    while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
334	    if (i >= css.length) break;
335	    // Handle at-rules
336	    if (css[i] === "@") {
337	      let atRule = "";
338	      let j = i;
339	      while (j < css.length && css[j] !== "{" && css[j] !== ";") { atRule += css[j]; j++; }
340	      const atName = atRule.trim().toLowerCase();
341	      // @keyframes and @font-face: pass through without scoping
342	      if (atName.startsWith("@keyframes") || atName.startsWith("@font-face")) {
343	        result += atRule;
344	        if (j < css.length && css[j] === "{") {
345	          let depth = 1; result += css[j]; j++;
346	          while (j < css.length && depth > 0) {
347	            if (css[j] === "{") depth++;
348	            if (css[j] === "}") depth--;
349	            result += css[j]; j++;
350	          }
351	        }
352	        i = j; continue;
353	      }
354	      // @media: recursively scope inner rules
355	      if (atName.startsWith("@media")) {
356	        result += atRule;
357	        if (j < css.length && css[j] === "{") {
358	          result += "{"; j++;
359	          let depth = 1; let inner = "";
360	          while (j < css.length && depth > 0) {
361	            if (css[j] === "{") depth++;
362	            if (css[j] === "}") depth--;
363	            if (depth > 0) inner += css[j];
364	            j++;
365	          }
366	          result += scopeAdminCss(inner, wid);
367	          result += "}";
368	        }
369	        i = j; continue;
370	      }
371	    }
372	    // Regular rule: grab selector, prefix with #wid
373	    let sel = "";
374	    let body = "";
375	    while (i < css.length && css[i] !== "{") { sel += css[i]; i++; }
376	    if (i < css.length) i++; // skip {
377	    let depth = 1;
378	    while (i < css.length && depth > 0) {
379	      if (css[i] === "{") depth++;
380	      if (css[i] === "}") depth--;
381	      if (depth > 0) body += css[i];
382	      i++;
383	    }
384	    if (sel.trim()) {
385	      const prefixed = sel.split(",").map(s => {
386	        s = s.trim();
387	        return s ? "#" + wid + " " + s : "";
388	      }).filter(Boolean).join(", ");
389	      result += prefixed + " {" + body + "}";
390	    }
391	  }
392	  return result;
393	}
